import { PHOTO } from "~/lib/catalog/photos";

/** Widths generated by scripts/photos.mjs into public/photos/w/<key>-<w>.webp. */
const WIDTHS = [480, 800, 1200, 1600, 2000];

const srcSetFor = (src: string, w: number) => {
  const key = src.replace(/^\/photos\//, "").replace(/\.\w+$/, "");
  const widths = WIDTHS.filter((x) => x <= w);
  return widths.length ? widths.map((x) => `/photos/w/${key}-${x}.webp ${x}w`).join(", ") : undefined;
};

/**
 * A photograph from the house library, by key, filling a sized relative parent.
 * Serves the WebP width variants in a srcset; the original file is the fallback src.
 * `tall` names an art-directed source for phones (a 4:5 frame of the same picture).
 * When photography moves to Shopify Files this becomes a CDN srcset with the same props.
 */
export function Pic({
  k,
  tall,
  sizes = "100vw",
  priority = false,
  className = "",
  position,
  fit = "cover",
}: {
  k: string;
  /** the phone source (below 768px), another key in the library */
  tall?: string;
  sizes?: string;
  priority?: boolean;
  className?: string;
  position?: string;
  /** contain: the whole object shown, on the page's own ground (product first frames) */
  fit?: "cover" | "contain";
}) {
  const p = PHOTO[k] ?? PHOTO["hero-box"];
  const t = tall ? PHOTO[tall] : undefined;
  // A packshot on white floats on the paper (multiply): the photograph's ground becomes the page's, no tile edge.
  const float = p.float ? "float" : "";
  const img = (
    <img
      src={p.src}
      srcSet={srcSetFor(p.src, p.w)}
      alt={p.alt}
      width={p.w}
      height={p.h}
      sizes={sizes}
      loading={priority ? "eager" : "lazy"}
      fetchPriority={priority ? "high" : undefined}
      decoding={priority ? "sync" : "async"}
      className={`absolute inset-0 h-full w-full ${fit === "contain" ? "object-contain" : "object-cover"} ${float} ${className}`}
      style={position ? { objectPosition: position } : undefined}
    />
  );
  if (!t) return img;
  return (
    <picture>
      <source media="(max-width: 767px)" srcSet={srcSetFor(t.src, t.w) ?? t.src} sizes="100vw" width={t.w} height={t.h} />
      {img}
    </picture>
  );
}
